// Des: Weekly vendor keepalive and random pack download verify
// Flo: keepalive: list on each store, SELECT 1 on each database, outcome feeds failover | verify: download N random packs, check every entry hash, copy equals primary; bad > requeue from local raw or count as lost
// I/O: Sync (pool of stores and databases + local Db) + clock (caller) > Kres; both jobs run at most once per interval; dryz skips the network
// ===================================================================
const std = @import("std"); const sync = @import("sy-clou-sync.zig"); const outb = @import("sy-clou-outb.zig"); const fail = @import("ru-fail-over.zig"); const pack = @import("ru-purg-pack.zig"); const hash = @import("ut-hash-dedu.zig");
const CF = .{ .dayz = 86400000, .keyk = "keepalive/", .pinq = "SELECT 1", .live = "live_last", .veri = "veri_last" };
pub const Kres = struct { ping: u32 = 0, pbad: u32 = 0, veri: u32 = 0, vbad: u32 = 0, lost: u32 = 0, fixd: u32 = 0, cops: u32 = 0, ranz: bool = false };
fn noteOutc(self: *sync.Sync, name: []const u8, nowz: i64, errz: ?anyerror, rslt: *Kres) !void { rslt.ping += 1; if (errz) |err3| { rslt.pbad += 1; try fail.failBadz(self.dbzz, name, nowz, err3 == error.CloudDeny, self.conf.clou_fail_runs); } else try fail.failPing(self.dbzz, name, nowz); }
pub fn liveRunz(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64) !Kres { var rslt: Kres = .{}; if (self.dryz) return rslt; const last = try fail.flagGetz(self.dbzz, CF.live); if (last > 0 and nowz - last < @as(i64, self.conf.purg_live_days) * CF.dayz) return rslt; rslt.ranz = true; for (self.pool) |item| { var errz: ?anyerror = null; _ = item.store.list(item.store.ctx2, aren, self.iozz, CF.keyk) catch |err3| { errz = err3; }; try noteOutc(self, item.name, nowz, errz, &rslt); } for (self.sqls) |item| { var errz: ?anyerror = null; const stmz = [_][]const u8{CF.pinq}; item.sql2.exec(item.sql2.ctx2, aren, self.iozz, &stmz) catch |err3| { errz = err3; }; try noteOutc(self, item.name, nowz, errz, &rslt); } try fail.flagSetz(self.dbzz, CF.live, nowz); return rslt; }
const Lent = struct { hexz: []const u8, offs: i64, lenz: i64 };
fn entsLoca(self: *sync.Sync, aren: std.mem.Allocator, key2: []const u8) ![]Lent { var stmt = try self.dbzz.prep("SELECT hexz,offs,lenz FROM pack WHERE packk=?1;"); defer stmt.fini(); try stmt.bindText(1, key2); var list: std.ArrayList(Lent) = .empty; while (try stmt.step()) try list.append(aren, .{ .hexz = try aren.dupe(u8, stmt.colzText(0)), .offs = stmt.colzIntz(1), .lenz = stmt.colzIntz(2) }); return list.toOwnedSlice(aren); }
fn packOkay(aren: std.mem.Allocator, byts: []const u8, ents: []const Lent) bool { for (ents) |entr| { const offs: usize = @intCast(entr.offs); const lenz: usize = @intCast(entr.lenz); if (offs + lenz > byts.len or !pack.partOkay(aren, entr.hexz, byts[offs .. offs + lenz])) return false; } return true; }
fn haveLoca(self: *sync.Sync, aren: std.mem.Allocator, hexz: []const u8) bool { if (hexz.len != 64) return false; var buff: [96]u8 = undefined; const rela = hash.hashPath(&buff, hexz[0..64].*) catch return false; const path = std.fs.path.join(aren, &.{ self.dirz, "raw", rela }) catch return false; _ = std.Io.Dir.cwd().statFile(self.iozz, path, .{}) catch return false; return true; }
fn badzPack(self: *sync.Sync, aren: std.mem.Allocator, key2: []const u8, ents: []const Lent, nowz: i64, rslt: *Kres) !void { rslt.vbad += 1; for (ents) |entr| { if (haveLoca(self, aren, entr.hexz)) { try outb.outbAddz(self.dbzz, "file", entr.hexz, nowz, true); rslt.fixd += 1; } else rslt.lost += 1; } var stmt = try self.dbzz.prep("UPDATE pack SET vfyz=0 WHERE packk=?1;"); defer stmt.fini(); try stmt.bindText(1, key2); _ = try stmt.step(); }
fn copyChek(self: *sync.Sync, aren: std.mem.Allocator, key2: []const u8, byts: []const u8, nowz: i64, rslt: *Kres) !void { if (pack.packGenz(key2) != 1 or !self.conf.purg_copy_enab) return; const cop2 = self.copy orelse return; const back = cop2.get(cop2.ctx2, aren, self.iozz, key2) catch { try outb.outbAddz(self.dbzz, "copy", key2, nowz, true); rslt.cops += 1; return; }; if (!std.mem.eql(u8, back, byts)) { try outb.outbAddz(self.dbzz, "copy", key2, nowz, true); rslt.cops += 1; } }
pub fn veriRunz(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64) !Kres { var rslt: Kres = .{}; if (self.dryz or self.conf.purg_veri_cont == 0) return rslt; const last = try fail.flagGetz(self.dbzz, CF.veri); if (last > 0 and nowz - last < @as(i64, self.conf.purg_veri_days) * CF.dayz) return rslt; rslt.ranz = true; var stmt = try self.dbzz.prep("SELECT packk,max(vend) FROM pack GROUP BY packk ORDER BY random() LIMIT ?1;"); defer stmt.fini(); try stmt.bindIntz(1, self.conf.purg_veri_cont); const Pick = struct { key2: []const u8, vend: []const u8 }; var list: std.ArrayList(Pick) = .empty; while (try stmt.step()) try list.append(aren, .{ .key2 = try aren.dupe(u8, stmt.colzText(0)), .vend = try aren.dupe(u8, stmt.colzText(1)) });
for (list.items) |pick| { const ents = try entsLoca(self, aren, pick.key2); const sto2 = sync.storOfzz(self, pick.vend); const byts = sto2.get(sto2.ctx2, aren, self.iozz, pick.key2) catch { try badzPack(self, aren, pick.key2, ents, nowz, &rslt); continue; }; if (!packOkay(aren, byts, ents)) { try badzPack(self, aren, pick.key2, ents, nowz, &rslt); continue; } var updz = try self.dbzz.prep("UPDATE pack SET vfyz=?2 WHERE packk=?1;"); defer updz.fini(); try updz.bindText(1, pick.key2); try updz.bindIntz(2, nowz); _ = try updz.step(); rslt.veri += 1; try copyChek(self, aren, pick.key2, byts, nowz, &rslt); } try fail.flagSetz(self.dbzz, CF.veri, nowz); return rslt; }
